//! A port of protodiffgen's `apply` package: computes, applies and checks
//! protodiffgen diffs by reflection.
//!
//! This is the Go package `github.com/nexteggapp/protodiffgen/apply` at
//! commit b2e70a4 (Apache-2.0, the same copyright holder as this
//! repository), file for file: `apply.go`, `diff.go`, `equal.go`,
//! `myers.go`, `overlap.go`, `plan.go`, `target.go` and `validate.go`, and
//! the parts of `internal/schema` they use. Its error texts are Go's, byte
//! for byte, because taxyear puts them in problems a person reads.
//!
//! A diff is a message generated by protodiffgen from a target message and
//! a config of list rules (see the design in protodiffgen's
//! `docs/design.md`): which fields it sets or clears, and which list items
//! it adds, removes or patches by key or by index. Go works on
//! `protoreflect`; this port works on buffa-descriptor's [`DynamicMessage`]
//! over a [`DescriptorPool`], with the generated messages' options read
//! from the pool's descriptors, so it needs no generated code of its own.
//!
//! The `*_dynamic` functions are Go's, on dynamic messages. [`apply`],
//! [`validate`], [`diff`], [`equal`] and [`overlap`] take buffa's generated
//! messages instead, converting them through [`DynamicMessage`] over the
//! pool of every taxcalcs schema, [`pool`].
//!
//! Two things differ from Go where Go's own answer depends on its map
//! iteration order: when a message has unknown fields in more than one
//! place, or more than one item of a map fails a check, the one reported is
//! the first in field-number and key order.

use std::sync::{Arc, LazyLock};

use buffa_descriptor::{DescriptorPool, DynamicMessage};

mod apply;
mod diff;
mod dynamic;
mod equal;
mod myers;
mod overlap;
mod plan;
mod schema;
mod target;
mod validate;

pub use apply::apply_dynamic;
pub use diff::diff_dynamic;
pub use equal::equal_dynamic;
pub use overlap::{Item, Step, overlap_dynamic};
pub use target::Target;
pub use validate::validate_dynamic;

/// Why a diff can't be computed or applied. Its text is the Go error's.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
pub enum Error {
    /// The diff's type is not a protodiffgen patch body, or doesn't diff the
    /// target's type: plan.go's errors.
    #[error("{0}")]
    Schema(String),
    /// The messages are of the wrong types for the call, such as a and b of
    /// two types.
    #[error("{0}")]
    Mismatch(String),
    /// The diff doesn't apply to its target, or a message has unknown
    /// fields or a keyed list with an unset or repeated key: validate.go's
    /// errors.
    #[error("{0}")]
    Refused(String),
    /// A generated message couldn't be converted to or from a dynamic one,
    /// which Go, working on generated messages directly, never has to do.
    #[error("protodiffgen: {0}")]
    Convert(String),
}

static POOL: LazyLock<Result<Arc<DescriptorPool>, String>> = LazyLock::new(|| {
    DescriptorPool::decode(proto::DESCRIPTORS)
        .map(Arc::new)
        .map_err(|e| e.to_string())
});

/// The pool of every schema the taxcalcs crates use, from
/// [`proto::DESCRIPTORS`], which the typed functions convert through.
///
/// # Errors
///
/// When the descriptors don't load, which would be a broken build.
pub fn pool() -> Result<&'static Arc<DescriptorPool>, Error> {
    POOL.as_ref().map_err(|e| Error::Convert(e.clone()))
}

/// m as a dynamic message of the taxcalcs pool.
///
/// # Errors
///
/// When m's type is not in the pool.
pub fn to_dynamic<M: buffa::Message + buffa::MessageName>(m: &M) -> Result<DynamicMessage, Error> {
    DynamicMessage::try_from_message(m, Arc::clone(pool()?))
        .map_err(|e| Error::Convert(e.to_string()))
}

/// A dynamic message as the generated message M.
///
/// # Errors
///
/// When m is not an M.
pub fn from_dynamic<M: buffa::Message + Default>(m: &DynamicMessage) -> Result<M, Error> {
    m.to_message().map_err(|e| Error::Convert(e.to_string()))
}

/// An empty dynamic message of M's type.
fn empty<M: buffa::MessageName>() -> Result<DynamicMessage, Error> {
    let pool = pool()?;
    DynamicMessage::new_by_name(Arc::clone(pool), M::FULL_NAME)
        .ok_or_else(|| Error::Convert(format!("{} is not in the descriptors", M::FULL_NAME)))
}

/// Validates d against a, then returns a with d applied. a is not changed.
/// It is [`apply_dynamic`] on generated messages.
///
/// # Errors
///
/// Why d doesn't apply to a.
pub fn apply<M, D>(a: &M, d: &D) -> Result<M, Error>
where
    M: buffa::Message + buffa::MessageName + Default,
    D: buffa::Message + buffa::MessageName,
{
    from_dynamic(&apply_dynamic(&to_dynamic(a)?, &to_dynamic(d)?)?)
}

/// Reports whether d can be applied to a: [`validate_dynamic`] on generated
/// messages.
///
/// # Errors
///
/// The refusal.
pub fn validate<M, D>(a: &M, d: &D) -> Result<(), Error>
where
    M: buffa::Message + buffa::MessageName,
    D: buffa::Message + buffa::MessageName,
{
    validate_dynamic(&to_dynamic(a)?, &to_dynamic(d)?)
}

/// Writes into out the smallest diff from a to b: [`diff_dynamic`] on
/// generated messages. out is reset first.
///
/// # Errors
///
/// When D doesn't diff M, or a or b fails the target check.
pub fn diff<M, D>(a: &M, b: &M, out: &mut D) -> Result<(), Error>
where
    M: buffa::Message + buffa::MessageName,
    D: buffa::Message + buffa::MessageName + Default,
{
    let mut d = empty::<D>()?;
    diff_dynamic(&to_dynamic(a)?, &to_dynamic(b)?, &mut d)?;
    *out = from_dynamic(&d)?;
    Ok(())
}

/// Reports whether x and y are equal under the list rules of D, the diff
/// type: [`equal_dynamic`] on generated messages. It is false when a
/// message can't be converted.
pub fn equal<M, D>(x: &M, y: &M, diff: &D) -> bool
where
    M: buffa::Message + buffa::MessageName,
    D: buffa::Message + buffa::MessageName,
{
    match (to_dynamic(x), to_dynamic(y), to_dynamic(diff)) {
        (Ok(x), Ok(y), Ok(d)) => equal_dynamic(&x, &y, &d),
        _ => false,
    }
}

/// Lists where two diffs of one base both change something:
/// [`overlap_dynamic`] on generated messages.
///
/// # Errors
///
/// When D is not a patch body.
pub fn overlap<D>(d1: &D, d2: &D) -> Result<Vec<Item>, Error>
where
    D: buffa::Message + buffa::MessageName,
{
    overlap_dynamic(&to_dynamic(d1)?, &to_dynamic(d2)?)
}
